
import React, { useMemo } from 'react';
import { Package, Factory, TrendingUp, AlertCircle } from 'lucide-react';

// Images (Relative paths assuming they are in the public/assets or accessible)
// Since we generated them, we'll assume they are served. If not, we fall back to icons.
// For now, I will use the path convention used in the system, or just pass the absolute path for local render if possible, 
// but for a React app typically these go in `public`.
// I will use the file:// protocol if this is a local electron-like renderer, or relative.
// Given strict browser security, local file paths often fail. I will assume standard import or specific path handling.
// For this environment, I'll use the 'file:///' prefix with the absolute path I know, as the user environment seems local.

const GINGER_IMG = "data:image/png;base64,";
const GARLIC_IMG = "data:image/png;base64,";

const MetricCard = ({ title, value, subtext, icon: Icon, trend, image }) => (
    <div style={{
        background: 'rgba(255, 255, 255, 0.03)',
        border: '1px solid rgba(255, 255, 255, 0.1)',
        borderRadius: '1rem',
        padding: '1.5rem',
        position: 'relative',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
        minHeight: '200px'
    }}>
        <div style={{
            position: 'absolute', top: 0, right: 0, padding: '1rem', opacity: 0.1
        }}>
            {Icon && <Icon size={60} />}
        </div>

        {/* Helper Image Overlay if provided */}
        {image && (
            <div style={{
                position: 'absolute', top: '1rem', right: '1rem', width: '60px', height: '60px',
                opacity: 0.8, borderRadius: '50%', overflow: 'hidden', border: '2px solid var(--glass-border)'
            }}>
                <img src={image} alt="icon" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            </div>
        )}

        <div style={{ position: 'relative', zIndex: 10 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
                <div style={{ padding: '0.5rem', borderRadius: '0.5rem', background: 'rgba(59, 130, 246, 0.2)', color: '#60a5fa' }}>
                    {Icon && <Icon size={20} />}
                </div>
                <h3 style={{ color: 'var(--text-secondary)', fontSize: '0.875rem', fontWeight: 500, margin: 0 }}>{title}</h3>
            </div>
            <div style={{ fontSize: '1.875rem', fontWeight: 700, color: 'var(--text-primary)', marginBottom: '0.5rem' }}>
                {value}
            </div>
            <div style={{
                fontSize: '0.75rem', fontWeight: 500, display: 'flex', alignItems: 'center', gap: '0.25rem',
                color: trend === 'up' ? '#34d399' : trend === 'down' ? '#f43f5e' : '#34d399'
            }}>
                {subtext}
            </div>
        </div>
    </div>
);

const ProductionDashboard = ({ data = {}, selectedMonth, selectedYear }) => {
    // Data processing starts immediately (Hooks must be unconditional)

    // Filter data based on selection
    // Filter data based on selection
    const filterByMonth = (items) => {
        if (!items) return [];
        if (selectedMonth === 'Overall') {
            // Strict Year Filtering
            if (selectedYear) {
                return items.filter(item => item.date && item.date.startsWith(selectedYear));
            }
            return items;
        }
        const [selMonth, selYear] = selectedMonth.split(' ');
        const monthMap = { Jan: '01', Feb: '02', Mar: '03', Apr: '04', May: '05', Jun: '06', Jul: '07', Aug: '08', Sep: '09', Oct: '10', Nov: '11', Dec: '12' };
        const targetPrefix = `${selYear}-${monthMap[selMonth]}`;
        return items.filter(item => item.date && item.date.startsWith(targetPrefix));
    };

    const stockIn = useMemo(() => filterByMonth(data.stockIn), [data, selectedMonth, selectedYear]);
    const preProd = useMemo(() => filterByMonth(data.preProduction), [data, selectedMonth, selectedYear]);
    const postProd = useMemo(() => filterByMonth(data.postProduction), [data, selectedMonth, selectedYear]);

    // KPI Calculations
    const totalStockVal = stockIn.reduce((sum, item) => sum + item.weight, 0);
    const totalOutput = postProd.reduce((sum, item) => sum + item.weight, 0);

    // Ginger & Garlic Specifics
    let gingerIn = 0, gingerOut = 0;
    let garlicIn = 0, garlicOut = 0;
    const normalizeStr = (str) => String(str).toLowerCase();

    // Prepare Split Lists for "Production Input" Box
    const gingerUsageList = [];
    const garlicUsageList = [];

    // --- Stock Logic: Cumulative Balance ---
    // Efficiently calculate Opening + In - Out up to selected month end
    const cumulativeBalances = useMemo(() => {
        if (!data.stockIn || !data.preProduction) return { ginger: 0, garlic: 0 };

        let limitDate = '9999-12-31'; // Default: Include Everything

        if (selectedMonth !== 'Overall') {
            const [selMonth, selYear] = selectedMonth.split(' ');
            const monthMap = { Jan: '01', Feb: '02', Mar: '03', Apr: '04', May: '05', Jun: '06', Jul: '07', Aug: '08', Sep: '09', Oct: '10', Nov: '11', Dec: '12' };
            // Calculate "Next Month" prefix to filter strictly < Next Month
            let mInt = parseInt(monthMap[selMonth]);
            let yInt = parseInt(selYear);

            mInt++;
            if (mInt > 12) { mInt = 1; yInt++; }

            const mStr = String(mInt).padStart(2, '0');
            limitDate = `${yInt}-${mStr}`; // e.g., "2024-12"
        }

        // Helper for cumulative sum
        const calcSum = (items, key) => items.reduce((sum, item) => {
            // Include if item.date < limitDate (Strictly less than start of next month)
            // item.date (YYYY-MM-DD) < "YYYY-MM" works for comparison
            if (item.date && item.date < limitDate) {
                const mat = normalizeStr(item.material);
                if (mat.includes(key)) return sum + item.weight;
            }
            return sum;
        }, 0);

        const gingerInTotal = calcSum(data.stockIn, 'ginger');
        const garlicInTotal = calcSum(data.stockIn, 'garlic');
        const gingerOutTotal = calcSum(data.preProduction, 'ginger');
        const garlicOutTotal = calcSum(data.preProduction, 'garlic');

        return {
            ginger: gingerInTotal - gingerOutTotal,
            garlic: garlicInTotal - garlicOutTotal
        };

    }, [data, selectedMonth, selectedYear]);

    // --- Production Logic: Flow (Selected Month Only) ---
    // --- Production Input Logic ---
    // User Request: Pre Production(excel) = Production Input(dashboard)
    // We simply sum the filtered preProd array.
    const totalPreProd = preProd.reduce((sum, item) => sum + item.weight, 0);
    const sortedPreProd = [...preProd].sort((a, b) => b.date.localeCompare(a.date));

    // Helper to identify Opening Stock - MADE MORE ROBUST FOR DEBUGGING
    const isOS = (item) => {
        if (!item || !item.material) return false;
        // Fix: Convert to string safely before trim to prevent crash on numbers
        const matUpper = String(item.material).trim().toUpperCase();
        if (matUpper.includes('PASTE') || matUpper.includes('PEELED')) return false;

        // Broader checks for Opening Stock
        const isOpening =
            matUpper.startsWith('OS') ||
            matUpper.startsWith('O.S') ||
            matUpper.includes('OPENING') ||
            matUpper.includes('B/F');

        return isOpening;
    };

    // DEBUG: Normalize Helper (Ensuring we have it if it was missing/hard to find, or just use local)
    // If it already exists, this might shadow it, but if it's 'var' or function it might be fine.
    // Safest is to use a local name if we aren't sure.


    // Helper: Normalize String (Renamed to avoid conflict)
    const localNormalizeStr = (str) => String(str || '').toLowerCase().trim();

    // Calculate Monthly Ledger for Stock (Sequential)
    const monthlyStockLedger = useMemo(() => {
        if (!data.stockIn || !data.preProduction) return {};


        // 1. Gather all unique months and sort them
        const allDates = [
            ...data.stockIn.map(i => i.date),
            ...data.preProduction.map(i => i.date)
        ].filter(d => d);

        // Helper to get YYYY-MM
        const getMonthKey = (dateStr) => {
            // dateStr is YYYY-MM-DD
            return dateStr.substring(0, 7);
        };

        const uniqueMonths = [...new Set(allDates.map(getMonthKey))].sort();

        const ledger = {};
        let runningGinger = 0;
        let runningGarlic = 0;

        uniqueMonths.forEach(monthKey => {
            // Filter items for this month
            const inItemsAll = data.stockIn.filter(i => i.date && i.date.startsWith(monthKey));
            const outItems = data.preProduction.filter(i => i.date && i.date.startsWith(monthKey));

            // Separate OS (Opening Stock) explicitly
            // isOS is defined at component level now

            const osItems = inItemsAll.filter(isOS);
            const purchaseItems = inItemsAll.filter(i => !isOS(i));

            // Explicit Opening (Sum of OS rows for this month)
            const explicitGingerOS = osItems.reduce((acc, i) => {
                const norm = localNormalizeStr(i.material);
                return (norm.includes('ginger') && !norm.includes('garlic') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);
            const explicitGarlicOS = osItems.reduce((acc, i) => {
                const norm = localNormalizeStr(i.material);
                return (norm.includes('garlic') && !norm.includes('ginger') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);

            // Purchases (In)
            const gingerIn = purchaseItems.reduce((acc, i) => {
                const norm = localNormalizeStr(i.material);
                return (norm.includes('ginger') && !norm.includes('garlic') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);
            const garlicIn = purchaseItems.reduce((acc, i) => {
                const norm = localNormalizeStr(i.material);
                return (norm.includes('garlic') && !norm.includes('ginger') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);

            // Usage (Out)
            const gingerOut = outItems.reduce((acc, i) => {
                const norm = localNormalizeStr(i.material);
                return (norm.includes('ginger') && !norm.includes('garlic') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);
            const garlicOut = outItems.reduce((acc, i) => {
                const norm = localNormalizeStr(i.material);
                return (norm.includes('garlic') && !norm.includes('ginger') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);

            // Calculate Opening for THIS month
            // Logic Fix: Use Explicit OS (File Truth) if available. Else use Running Balance (Continuity).
            const gingerOpening = explicitGingerOS > 0 ? explicitGingerOS : runningGinger;
            const garlicOpening = explicitGarlicOS > 0 ? explicitGarlicOS : runningGarlic;

            // Calculate Closing
            const gingerClosing = gingerOpening + gingerIn - gingerOut;
            const garlicClosing = garlicOpening + garlicIn - garlicOut;

            // Update running balance
            runningGinger = gingerClosing;
            runningGarlic = garlicClosing;

            ledger[monthKey] = {
                ginger: { opening: gingerOpening, in: gingerIn, out: gingerOut, closing: gingerClosing },
                garlic: { opening: garlicOpening, in: garlicIn, out: garlicOut, closing: garlicClosing }
            };
        });

        // 'Overall' key for latest closing
        ledger['Overall'] = {
            ginger: { closing: runningGinger },
            garlic: { closing: runningGarlic }
        };

        return ledger;
    }, [data]);

    // Determine Stock Value based on Selection
    let gingerBalance = 0;
    let garlicBalance = 0;
    let balanceLabel = "Total Purchase (Stock In)";
    let availableLabel = "Currently Available";

    let gingerAvailable = 0;
    let garlicAvailable = 0;

    let gingerOpening = 0;
    let garlicOpening = 0;

    if (selectedMonth === 'Overall') {
        // --- OVERALL VIEW (Yearly Filtered) ---

        // 1. Calculate Totals (Purchased / Opening) based on Year
        if (data.stockIn) {
            const yearItems = data.stockIn.filter(i => i.date && i.date.startsWith(selectedYear));
            const purchaseItems = yearItems.filter(i => !isOS(i));
            const osItems = yearItems.filter(isOS);

            gingerBalance = purchaseItems.reduce((acc, i) => {
                const norm = normalizeStr(i.material);
                return (norm.includes('ginger') && !norm.includes('garlic') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);
            garlicBalance = purchaseItems.reduce((acc, i) => {
                const norm = normalizeStr(i.material);
                return (norm.includes('garlic') && !norm.includes('ginger') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);

            gingerOpening = osItems.reduce((acc, i) => {
                const norm = normalizeStr(i.material);
                return (norm.includes('ginger') && !norm.includes('garlic') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);
            garlicOpening = osItems.reduce((acc, i) => {
                const norm = normalizeStr(i.material);
                return (norm.includes('garlic') && !norm.includes('ginger') && !norm.includes('paste') && !norm.includes('peeled')) ? acc + i.weight : acc;
            }, 0);
        }

        // 2. Determine Available Stock (Closing of Last Active Month in Selection)
        const yearMonths = Object.keys(monthlyStockLedger)
            .filter(k => k.startsWith(selectedYear) && k !== 'Overall')
            .sort();

        if (yearMonths.length > 0) {
            const lastMonthKey = yearMonths[yearMonths.length - 1];
            if (monthlyStockLedger[lastMonthKey]) {
                gingerAvailable = monthlyStockLedger[lastMonthKey].ginger.closing;
                garlicAvailable = monthlyStockLedger[lastMonthKey].garlic.closing;
            }
        } else {
            // No data for this year
            gingerAvailable = 0;
            garlicAvailable = 0;
        }

    } else {
        // --- MONTHLY VIEW ---
        const [sMonth, sYear] = selectedMonth.split(' ');
        const monthMap = { Jan: '01', Feb: '02', Mar: '03', Apr: '04', May: '05', Jun: '06', Jul: '07', Aug: '08', Sep: '09', Oct: '10', Nov: '11', Dec: '12' };
        const key = `${sYear}-${monthMap[sMonth]}`;

        if (monthlyStockLedger[key]) {
            gingerBalance = monthlyStockLedger[key].ginger.in;
            garlicBalance = monthlyStockLedger[key].garlic.in;
            gingerAvailable = monthlyStockLedger[key].ginger.closing;
            garlicAvailable = monthlyStockLedger[key].garlic.closing;
            gingerOpening = monthlyStockLedger[key].ginger.opening;
            garlicOpening = monthlyStockLedger[key].garlic.opening;
        }
    }

    const efficiency = totalPreProd > 0 ? ((totalOutput / totalPreProd) * 100).toFixed(1) : 0;

    // Sort logs by date desc
    const sortedStockIn = [...stockIn].sort((a, b) => b.date.localeCompare(a.date));
    const sortedPostProd = [...postProd].sort((a, b) => b.date.localeCompare(a.date));

    // Helper: Format Date to DD-MM-YYYY
    const formatDateFull = (isoString) => {
        if (!isoString) return '';
        const [yyyy, mm, dd] = isoString.split('-');
        return `${dd}-${mm}-${yyyy}`;
    };

    // Helper Table Component
    const DataTable = ({ title, count, color, items }) => (
        <div style={{
            background: 'var(--glass-highlight)',
            border: '1px solid var(--glass-border)',
            borderRadius: '1rem',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column',
            height: '100%',
            minHeight: '400px'
        }}>
            <div style={{
                padding: '1rem',
                background: 'var(--glass-highlight)',
                borderBottom: '1px solid var(--glass-border)',
                fontWeight: 600,
                color: color,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between'
            }}>
                <span>{title}</span>
                <span style={{ fontSize: '0.75rem', background: 'var(--glass-border)', padding: '0.1rem 0.5rem', borderRadius: '0.25rem', color: 'var(--text-primary)' }}>
                    {count} Records
                </span>
            </div>

            <div style={{
                display: 'grid', gridTemplateColumns: '90px 1fr 70px', gap: '0.5rem', padding: '0.5rem 0.75rem',
                borderBottom: '1px solid var(--glass-border)',
                fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-secondary)', textTransform: 'uppercase'
            }}>
                <div>Date</div>
                <div>Material</div>
                <div style={{ textAlign: 'right' }}>Kgs</div>
            </div>

            <div style={{ overflowY: 'auto', flex: 1, paddingBottom: '0.5rem' }} className="custom-scrollbar">
                {items.map((item, i) => {
                    // Use loose check for styling so "OS - Paste" gets highlighted even if excluded from calculation
                    const matUpper = String(item.material).trim().toUpperCase();
                    const isHighlightOS = matUpper.startsWith('OS') || matUpper.includes('OPENING') || matUpper.includes('B/F');

                    const rowColor = isHighlightOS ? '#f59e0b' : '#e5e7eb'; // Highlight OS (Dark Yellow)
                    const weightColor = isHighlightOS ? '#f59e0b' : color;

                    return (
                        <div key={i} style={{
                            display: 'grid', gridTemplateColumns: '90px 1fr 70px', gap: '0.5rem', padding: '0.5rem 0.75rem',
                            borderBottom: '1px solid var(--glass-border)',
                            fontSize: '0.875rem'
                        }}>
                            <div style={{ color: 'var(--text-secondary)', fontSize: '0.8rem' }}>{formatDateFull(item.date)}</div>
                            <div style={{ color: rowColor, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={item.material}>
                                {item.material}
                            </div>
                            <div style={{ textAlign: 'right', color: weightColor, fontWeight: 500 }}>
                                {item.weight.toFixed(1)}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );



    // Calculate Output Breakdown
    const outputBreakdown = useMemo(() => {
        const breakdown = {};
        postProd.forEach(item => {
            const name = item.material || 'Thej Paste'; // Fallback if name missing
            breakdown[name] = (breakdown[name] || 0) + item.weight;
        });
        return Object.entries(breakdown).sort((a, b) => b[1] - a[1]); // Sort by weight desc
    }, [postProd]);

    // Calculate Input Breakdown
    const inputBreakdown = useMemo(() => {
        const breakdown = {};
        preProd.forEach(item => {
            const name = item.material || 'Unknown Material';
            breakdown[name] = (breakdown[name] || 0) + item.weight;
        });
        return Object.entries(breakdown).sort((a, b) => b[1] - a[1]);
    }, [preProd]);

    if (stockIn.length === 0 && postProd.length === 0) {
        return (
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '16rem', color: 'var(--text-secondary)' }}>
                <Package size={48} style={{ marginBottom: '1rem', opacity: 0.5 }} />
                <p>No production data found for period: {selectedMonth}</p>
                <p style={{ fontSize: '0.875rem', marginTop: '0.5rem' }}>Try uploading (append) the "Daily Stocks" file again.</p>
            </div>
        );
    }



    return (
        <div className="animate-fade-in">
            {/* KPIs Grid */}
            <div style={{
                display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1.5rem', marginBottom: '2rem'
            }}>
                <MetricCard
                    title="Ginger Stock"
                    value={
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.2rem', marginTop: '2rem' }}>
                            {selectedMonth !== 'Overall' && (
                                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.8rem', color: '#f59e0b', fontWeight: 500 }}>
                                    <span>Opening:</span>
                                    <span>{gingerOpening.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                                </div>
                            )}
                            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem', color: gingerBalance < 0 ? '#ef4444' : '#38bdf8', fontWeight: 500 }}>
                                <span>Purchased:</span>
                                <span>{gingerBalance.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                            </div>
                            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem', color: 'var(--text-primary)', fontWeight: 500 }}>
                                <span>Total:</span>
                                <span>{(gingerOpening + gingerBalance).toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                            </div>
                            <div style={{
                                display: 'flex', justifyContent: 'space-between', fontSize: '1.25rem', color: gingerAvailable < 0 ? '#ef4444' : 'white', fontWeight: 700,
                                borderTop: '1px solid var(--glass-border)', paddingTop: '0.3rem', marginTop: '0.1rem'
                            }}>
                                <span>Available:</span>
                                <span title={`(Opening + Purchased) - Used`}>{gingerAvailable.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                            </div>
                        </div>
                    }
                    subtext={availableLabel}

                    trend="neutral"
                    image={GINGER_IMG}
                />
                <MetricCard
                    title="Garlic Stock"
                    value={
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.2rem', marginTop: '2rem' }}>
                            {selectedMonth !== 'Overall' && (
                                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.8rem', color: '#f59e0b', fontWeight: 500 }}>
                                    <span>Opening:</span>
                                    <span>{garlicOpening.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                                </div>
                            )}
                            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem', color: garlicBalance < 0 ? '#ef4444' : '#38bdf8', fontWeight: 500 }}>
                                <span>Purchased:</span>
                                <span>{garlicBalance.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                            </div>
                            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem', color: 'var(--text-primary)', fontWeight: 500 }}>
                                <span>Total:</span>
                                <span>{(garlicOpening + garlicBalance).toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                            </div>
                            <div style={{
                                display: 'flex', justifyContent: 'space-between', fontSize: '1.25rem', color: garlicAvailable < 0 ? '#ef4444' : 'white', fontWeight: 700,
                                borderTop: '1px solid var(--glass-border)', paddingTop: '0.3rem', marginTop: '0.1rem'
                            }}>
                                <span>Available:</span>
                                <span title={`(Opening + Purchased) - Used`}>{garlicAvailable.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                            </div>
                        </div>
                    }
                    subtext={availableLabel}

                    trend="neutral"
                    image={GARLIC_IMG}
                />
                <MetricCard
                    title="Production Input"
                    value={
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.2rem', marginTop: '0.5rem' }}>
                            {inputBreakdown.map(([name, weight]) => (
                                <div key={name} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem', color: '#f59e0b', fontWeight: 500 }}>
                                    <span style={{ marginRight: '0.5rem', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{name}:</span>
                                    <span style={{ whiteSpace: 'nowrap' }}>{weight.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                                </div>
                            ))}
                            <div style={{
                                display: 'flex', justifyContent: 'space-between', fontSize: '1.25rem', color: 'var(--text-primary)', fontWeight: 700,
                                borderTop: '1px solid var(--glass-border)', paddingTop: '0.3rem', marginTop: '0.1rem'
                            }}>
                                <span>Total:</span>
                                <span>{totalPreProd.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                            </div>
                        </div>
                    }
                    subtext="Used in Production"
                    icon={Factory}
                    trend="neutral"
                />
                <MetricCard
                    title="Total Output"
                    value={
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.2rem', marginTop: '0.5rem' }}>
                            {outputBreakdown.map(([name, weight]) => (
                                <div key={name} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem', color: '#34d399', fontWeight: 500 }}>
                                    <span style={{ marginRight: '0.5rem', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{name}:</span>
                                    <span style={{ whiteSpace: 'nowrap' }}>{weight.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                                </div>
                            ))}
                            <div style={{
                                display: 'flex', justifyContent: 'space-between', fontSize: '1.25rem', color: 'var(--text-primary)', fontWeight: 700,
                                borderTop: '1px solid var(--glass-border)', paddingTop: '0.3rem', marginTop: '0.1rem'
                            }}>
                                <span>Total:</span>
                                <span>{totalOutput.toLocaleString('en-IN', { maximumFractionDigits: 0 })} kg</span>
                            </div>
                        </div>
                    }
                    subtext="Finished Goods"
                    icon={TrendingUp}
                    trend="up"
                />
                <MetricCard
                    title="Efficiency"
                    value={`${efficiency}%`}
                    subtext="Conversion Rate"
                    icon={AlertCircle}
                    trend={parseFloat(efficiency) > 90 ? "up" : "down"}
                />
            </div>

            {/* Data Tables - 3 Column Layout */}
            <div style={{
                display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1.5rem', height: '600px'
            }}>
                <DataTable title="Stock In Log" count={sortedStockIn.length} color="#60a5fa" items={sortedStockIn} />
                <DataTable title="Production Input" count={sortedPreProd.length} color="#fbbf24" items={sortedPreProd} />
                <DataTable title="Finished Output" count={sortedPostProd.length} color="#34d399" items={sortedPostProd} />
            </div>


        </div>
    );
};



export default ProductionDashboard;
